WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"w2-english-class-1","subject":"english","title":"Describing Words and More Than One","summary":"Use describing words, make plurals, join ideas with and, but and because, and read a short story.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 2: Describing words","learning_objectives":["Use describing words to make sentences more interesting","Add s or es to make a word mean more than one","Join two ideas with and, but or because","Answer questions about a short story"],"tags":["week-2","adjectives","plurals","conjunctions"],"curriculum":{"course":"english-class-1","semester":1,"week":2}},"blocks":[{"type":"heading","text":"Welcome back, Word Explorer!"},{"type":"text","markdown":"Last week you met nouns and verbs.\n\nThis week we make our sentences more exciting.\n\nWe use describing words and joining words!"},{"type":"image","emoji":"🌈","alt":"Words can add colour to a sentence.","caption":"Words can add colour to a sentence."},{"type":"heading","text":"Stop 1: Describing words"},{"type":"text","markdown":"An **adjective** is a describing word. It tells us more about a noun.\n\nA ball is a noun. A big, red ball tells us more!"},{"type":"explainer","title":"Adding describing words","scenes":[{"caption":"A ball.","items":[{"id":"b","emoji":"⚽","x":50,"y":55,"size":3,"anim":"none","label":"ball"}]},{"caption":"A big ball. Big tells us the size.","items":[{"id":"b","emoji":"⚽","x":50,"y":55,"size":3,"anim":"grow","label":"big ball"}]},{"caption":"A big, round ball. Round tells us the shape.","items":[{"id":"b","emoji":"🏀","x":50,"y":55,"size":3,"anim":"pulse","label":"big, round ball"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which word is a describing word? The fluffy cat sat.","hint":"It tells us what the cat is like.","options":[{"id":"a","text":"cat"},{"id":"b","text":"fluffy"},{"id":"c","text":"sat"}],"answer":["b"]}},{"type":"image","emoji":"🐘🐜","alt":"A big elephant and a tiny ant. Big and tiny are describing words.","caption":"A big elephant and a tiny ant. Big and tiny are describing words."},{"type":"heading","text":"Stop 2: More than one"},{"type":"text","markdown":"A **plural** means more than one. We usually add **s**: one cat, two cats.\n\nIf a word ends in s, x, ch or sh, we add **es**: one box, two boxes."},{"type":"explainer","title":"One and many","scenes":[{"caption":"One cat.","items":[{"id":"c","emoji":"🐱","x":50,"y":55,"size":3,"anim":"none","label":"cat"}]},{"caption":"Two cats. We added s.","items":[{"id":"c","emoji":"🐱","x":35,"y":55,"size":3,"anim":"none"},{"id":"c2","emoji":"🐱","x":65,"y":55,"size":3,"anim":"grow","label":"cats"}]},{"caption":"One box. Two boxes. We added es.","items":[{"id":"c","emoji":"📦","x":35,"y":55,"size":3,"anim":"none","label":"box"},{"id":"c2","emoji":"📦","x":65,"y":55,"size":3,"anim":"grow"},{"id":"c3","emoji":"📦","x":85,"y":40,"size":2,"anim":"grow","label":"boxes"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"What is the plural of dog?","hint":"Just add one letter.","options":[{"id":"a","text":"doges"},{"id":"b","text":"dog''s"},{"id":"c","text":"dogs"}],"answer":["c"]}},{"type":"check","question":{"type":"multiple_choice","prompt":"What is the plural of dish?","hint":"It ends with sh.","options":[{"id":"a","text":"dishs"},{"id":"b","text":"dishes"},{"id":"c","text":"dishies"}],"answer":["b"]}},{"type":"manipulative","title":"Count and add s","goal":"Put 2 stars in each basket. Say ''one star'' and then ''two stars''.","emoji":"⭐","count":4,"zones":["Basket 1","Basket 2"]},{"type":"heading","text":"Stop 3: Joining words"},{"type":"text","markdown":"A **joining word** links two ideas. **And** adds, **but** shows a difference and **because** gives a reason.\n\nI like mangoes **and** apples. I like mangoes **but** not lemons. I wear a coat **because** it is cold."},{"type":"image","emoji":"🥭➕🍎","alt":"I like mangoes and apples. ''And'' joins two things.","caption":"I like mangoes and apples. ''And'' joins two things."},{"type":"check","question":{"type":"multiple_choice","prompt":"Fill in the joining word: I took an umbrella ___ it was raining.","hint":"It gives a reason.","options":[{"id":"a","text":"but"},{"id":"b","text":"and"},{"id":"c","text":"because"}],"answer":["c"]}},{"type":"reveal","prompt":"Can you finish this sentence? I am happy because ...","answer_markdown":"Any reason works. For example: I am happy because it is Eid!"},{"type":"heading","text":"Stop 4: Omar''s kite"},{"type":"text","markdown":"Read this story. Omar has a new kite. It is big and yellow. He runs in the park and the wind lifts the kite high. ''Look!'' says Omar. ''It is flying!''"},{"type":"image","emoji":"🪁🌳","alt":"Omar''s big yellow kite flies over the park.","caption":"Omar''s big yellow kite flies over the park."},{"type":"check","question":{"type":"multiple_choice","prompt":"What colour is Omar''s kite?","hint":"Read the second sentence.","options":[{"id":"a","text":"Red"},{"id":"b","text":"Blue"},{"id":"c","text":"Yellow"}],"answer":["c"]}},{"type":"brain_game","game":"remember_order","title":"Rainbow words","goal":"Watch the colours light up, then copy the order.","emojis":["🔴","🟡","🟢","🔵"]},{"type":"summary","points":["An adjective describes a noun.","A plural means more than one. Add s or es.","And, but and because join ideas."]},{"type":"callout","style":"tip","markdown":"Ready for the quiz? It has 15 questions and takes about 15 minutes."},{"type":"glossary","terms":[{"term":"adjective","meaning":"A describing word. It tells us more about a noun."},{"term":"plural","meaning":"A word that means more than one, like cats."},{"term":"s","meaning":"The letter we usually add to make a plural."},{"term":"es","meaning":"The letters we add to make a plural when a word ends in s, x, ch or sh."},{"term":"joining word","meaning":"A word that links two ideas, like and, but or because."},{"term":"and","meaning":"A joining word that adds one idea to another."},{"term":"but","meaning":"A joining word that shows a difference."},{"term":"because","meaning":"A joining word that gives a reason."}]}],"quiz":{"pass_percent":70,"shuffle_questions":true,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"multiple_choice","prompt":"Which word is a describing word? The tiny ant ran.","hint":"It tells us what the ant is like.","explanation":"Tiny describes the ant.","skill_tag":"adjectives.find","options":[{"id":"a","text":"ant"},{"id":"b","text":"ran"},{"id":"c","text":"tiny"}],"answer":["c"]},{"ref":"q2","type":"multi_select","prompt":"Which of these are describing words? Pick all that apply.","hint":"A describing word tells what something is like.","explanation":"Soft and round describe things. Run is a verb and ball is a noun.","skill_tag":"adjectives.find","options":[{"id":"a","text":"run"},{"id":"b","text":"ball"},{"id":"c","text":"round"},{"id":"d","text":"soft"}],"answer":["d","c"]},{"ref":"q3","type":"multiple_choice","prompt":"What is the plural of cat?","hint":"Add one letter.","explanation":"We add s to make most plurals.","skill_tag":"plurals.s","options":[{"id":"a","text":"cates"},{"id":"b","text":"cat''s"},{"id":"c","text":"catz"},{"id":"d","text":"cats"}],"answer":["d"]},{"ref":"q4","type":"multiple_choice","prompt":"What is the plural of fox?","hint":"It ends with x.","explanation":"After x, we add es.","skill_tag":"plurals.es","options":[{"id":"a","text":"foxies"},{"id":"b","text":"fox''s"},{"id":"c","text":"foxs"},{"id":"d","text":"foxes"}],"answer":["d"]},{"ref":"q5","type":"short_text","prompt":"Write the plural of bus.","hint":"It ends with s.","explanation":"After s, we add es: buses.","skill_tag":"plurals.es","answer":{"accepted":["buses","busses"]}},{"ref":"q6","type":"fill_blank","prompt":"Fill in the gaps.","hint":"Think about which letters to add.","explanation":"Box takes es and cat takes s.","skill_tag":"plurals.mix","points":2,"text":"One box, two {b1}. One cat, two {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"box"},{"id":"b","text":"boxes"},{"id":"c","text":"boxs"}]},{"id":"b2","options":[{"id":"a","text":"cat"},{"id":"b","text":"cats"},{"id":"c","text":"cates"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q7","type":"match","prompt":"Match each word to its plural.","hint":"Think about the ending of each word.","explanation":"Dogs adds s. Dishes and buses add es.","skill_tag":"plurals.match","points":2,"left":[{"id":"l1","text":"dog"},{"id":"l2","text":"dish"},{"id":"l3","text":"bus"}],"right":[{"id":"r2","text":"dishes"},{"id":"r3","text":"buses"},{"id":"r1","text":"dogs"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q8","type":"multiple_choice","prompt":"Fill in the joining word: I like tea ___ I do not like coffee.","hint":"It shows a difference.","explanation":"But shows that the two ideas are different.","skill_tag":"conjunctions.but","options":[{"id":"a","text":"and"},{"id":"b","text":"but"},{"id":"c","text":"because"}],"answer":["b"]},{"ref":"q9","type":"multiple_choice","prompt":"Fill in the joining word: She wore a hat ___ it was sunny.","hint":"It gives the reason.","explanation":"Because gives the reason for wearing a hat.","skill_tag":"conjunctions.because","options":[{"id":"a","text":"or"},{"id":"b","text":"because"},{"id":"c","text":"but"}],"answer":["b"]},{"ref":"q10","type":"order","prompt":"Put the words in order to make a sentence.","hint":"Start with The.","explanation":"The big dog barked. makes sense.","skill_tag":"sentences.order","points":2,"items":[{"id":"i3","text":"dog"},{"id":"i4","text":"barked."},{"id":"i2","text":"big"},{"id":"i1","text":"The"}],"answer":["i1","i2","i3","i4"]},{"ref":"q11","type":"true_false","prompt":"A describing word tells us more about a noun.","hint":"Think of ''big'' and ''red''.","explanation":"Adjectives describe nouns.","skill_tag":"adjectives.meaning","answer":[true]},{"ref":"q12","type":"hotspot","prompt":"Tap the picture of a big, round ball.","hint":"Look for a round one.","explanation":"The football is round.","skill_tag":"adjectives.picture","scene":{"items":[{"id":"h1","emoji":"⚽","label":"big round ball","x":20,"y":40,"size":3},{"id":"h2","emoji":"🏏","label":"cricket bat","x":50,"y":40,"size":3},{"id":"h3","emoji":"🎩","label":"hat","x":80,"y":40,"size":3},{"id":"h4","emoji":"🔺","label":"triangle","x":50,"y":80,"size":3}],"show_labels":true},"answer":["h1"]},{"ref":"q13","type":"slider","prompt":"How many letters do we add to make ''boxes'' from ''box''?","hint":"Count the new letters: es.","explanation":"We add e and s, which is 2 letters.","skill_tag":"plurals.es","range":{"step":1,"min":0,"max":5},"answer":{"value":2,"tolerance":0}},{"ref":"q14","type":"multiple_choice","prompt":"Omar has a new kite. It is big and yellow. What is the kite like?","hint":"Read the sentence again.","explanation":"The text says the kite is big and yellow.","skill_tag":"reading.literal","options":[{"id":"a","text":"Old and broken"},{"id":"b","text":"Big and yellow"},{"id":"c","text":"Small and red"}],"answer":["b"]},{"ref":"q15","type":"multiple_choice","prompt":"The wind lifts the kite high. What can you tell?","hint":"What lifts a kite?","explanation":"A kite flies when it is windy.","skill_tag":"reading.inference","options":[{"id":"a","text":"It is night"},{"id":"b","text":"It is windy"},{"id":"c","text":"It is snowing"}],"answer":["b"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT '15cab8b0-b1cc-5465-abaf-32d6908a99eb', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 103, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
INSERT OR IGNORE INTO course_lessons (course_id, lesson_id, position, semester, week) VALUES ('902cf72b-3cc6-5944-a208-0b4b9872a8c8', '15cab8b0-b1cc-5465-abaf-32d6908a99eb', 102, 1, 2);
INSERT OR IGNORE INTO quizzes (id, kind, lesson_id, version, is_current, pass_percent, shuffle_questions, shuffle_options, max_attempts) VALUES ('f1fcb7c7-d63a-575f-af77-fc51a96adc9f', 'lesson', '15cab8b0-b1cc-5465-abaf-32d6908a99eb', 1, 1, 70, 1, 1, NULL);
INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT 'f1fcb7c7-d63a-575f-af77-fc51a96adc9f' || ':' || json_extract(e.value,'$.ref'), 'f1fcb7c7-d63a-575f-af77-fc51a96adc9f', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) WHEN 'fill_blank' THEN json_object('text', json_extract(e.value,'$.text'), 'blanks', json_extract(e.value,'$.blanks')) WHEN 'hotspot' THEN json_object('scene', json_extract(e.value,'$.scene')) WHEN 'slider' THEN json_object('range', json_extract(e.value,'$.range')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = '15cab8b0-b1cc-5465-abaf-32d6908a99eb';
INSERT OR IGNORE INTO courses (id, slug, title, description, subject_id, age_band, status) VALUES ('736a0b85-b107-5f53-ab88-cda06a05f74b', 'english-class-4', 'English (Class 4)', 'English for Class 4', 'english', '9-10', 'published');
INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('10a07364-5786-5b8c-adf1-7f482a2bff8d', '736a0b85-b107-5f53-ab88-cda06a05f74b', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"w2-english-class-4","subject":"english","title":"Writing with Style","summary":"Make writing come alive with similes, metaphors, joining words and well-planned paragraphs.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 2: Writing","learning_objectives":["Tell a simile from a metaphor and use both","Join ideas with because, although and while","Plan a paragraph with a topic sentence and details","Build a strong description with an expanded noun phrase"],"tags":["week-2","similes","conjunctions","paragraphs"],"curriculum":{"course":"english-class-4","semester":1,"week":2}},"blocks":[{"type":"heading","text":"Welcome back, Wordsmith!"},{"type":"text","markdown":"Last week you looked at the jobs words do.\n\nThis week you will use those words like a real author.\n\nWe will paint pictures with language."},{"type":"image","emoji":"🖌️","alt":"Great writers paint pictures with words.","caption":"Great writers paint pictures with words."},{"type":"heading","text":"Stop 1: Similes and metaphors"},{"type":"text","markdown":"A **simile** compares two things using **like** or **as**. ''She was as quick as a cheetah.''\n\nA **metaphor** says one thing is another thing. ''The moon was a silver coin.''"},{"type":"explainer","title":"Simile or metaphor?","scenes":[{"caption":"The moon.","items":[{"id":"m","emoji":"🌙","x":50,"y":50,"size":3,"anim":"float"}]},{"caption":"Simile: The moon was like a silver coin.","items":[{"id":"m","emoji":"🌙","x":30,"y":50,"size":3,"anim":"float"},{"id":"c","emoji":"🪙","x":70,"y":50,"size":3,"anim":"pulse","label":"like"}]},{"caption":"Metaphor: The moon was a silver coin.","items":[{"id":"m","emoji":"🪙","x":50,"y":50,"size":3,"anim":"pulse","label":"was a coin"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which one is a simile?","hint":"Look for ''as'' or ''like''.","options":[{"id":"a","text":"She was brave."},{"id":"b","text":"She was as brave as a lion."},{"id":"c","text":"She was a lion."}],"answer":["b"]}},{"type":"check","question":{"type":"multiple_choice","prompt":"''The classroom was a zoo.'' What is this?","hint":"It does not use ''like'' or ''as''.","options":[{"id":"a","text":"A simile"},{"id":"b","text":"A question"},{"id":"c","text":"A metaphor"}],"answer":["c"]}},{"type":"callout","style":"fun_fact","markdown":"Writers all over the world use similes. In Urdu poems too, a smile can be ''bright as the moon''."},{"type":"heading","text":"Stop 2: Joining ideas"},{"type":"text","markdown":"A **conjunction** joins two ideas. **Because** gives a reason. **Although** shows a surprise. **While** shows two things happening at once.\n\nFatima took an umbrella **because** it was raining. **Although** it was cold, she went outside. She read **while** the rain fell."},{"type":"image","emoji":"☂️🌧️📖","alt":"Because, although and while join ideas.","caption":"Because, although and while join ideas."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which word fits? ___ the sun was hot, we played outside.","hint":"It shows a surprise.","options":[{"id":"a","text":"Because"},{"id":"b","text":"Although"},{"id":"c","text":"While"}],"answer":["b"]}},{"type":"check","question":{"type":"match","prompt":"Match the joining word to its job.","hint":"Think about each word.","points":2,"left":[{"id":"l1","text":"because"},{"id":"l2","text":"although"},{"id":"l3","text":"while"}],"right":[{"id":"r3","text":"two things at once"},{"id":"r1","text":"gives a reason"},{"id":"r2","text":"shows a surprise"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}}},{"type":"heading","text":"Stop 3: Painting with noun phrases"},{"type":"text","markdown":"An **expanded noun phrase** adds describing words to a noun. ''The tree'' becomes ''the tall, old tree by the river''.\n\nEach describing word helps the reader see a clearer picture."},{"type":"explainer","title":"Building a noun phrase","scenes":[{"caption":"The tree.","items":[{"id":"t","emoji":"🌳","x":50,"y":55,"size":3,"anim":"none","label":"the tree"}]},{"caption":"The tall tree.","items":[{"id":"t","emoji":"🌳","x":50,"y":50,"size":3,"anim":"grow","label":"the tall tree"}]},{"caption":"The tall, old tree by the river.","items":[{"id":"t","emoji":"🌳","x":35,"y":50,"size":3,"anim":"none","label":"tall, old tree"},{"id":"r","emoji":"🌊","x":75,"y":65,"size":3,"anim":"float","label":"by the river"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which is an expanded noun phrase?","hint":"It has extra describing detail.","options":[{"id":"a","text":"the tree"},{"id":"b","text":"the tall, old tree by the river"},{"id":"c","text":"ran quickly"}],"answer":["b"]}},{"type":"activity","title":"Describe a picture","materials":["Paper and pencil"],"instructions":["Look out of the window or at a photo.","Write one simple sentence about what you see.","Make it better with an expanded noun phrase, a simile and a joining word."]},{"type":"heading","text":"Stop 4: Paragraphs"},{"type":"text","markdown":"A **paragraph** is a group of sentences about one idea. It starts with a **topic sentence** that tells the reader the main idea. The next sentences add details.\n\nWhen you change to a new idea, start a new paragraph on a new line."},{"type":"explainer","title":"Building a paragraph","scenes":[{"caption":"The topic sentence says the main idea.","items":[{"id":"a","emoji":"📌","x":30,"y":25,"size":3,"anim":"pulse","label":"topic sentence"}]},{"caption":"Detail sentences add facts or description.","items":[{"id":"a","emoji":"📌","x":30,"y":25,"size":2,"anim":"none"},{"id":"b","emoji":"🔹","x":30,"y":50,"size":2,"anim":"grow","label":"detail"},{"id":"c","emoji":"🔹","x":30,"y":70,"size":2,"anim":"grow","label":"detail"}]},{"caption":"A new idea starts a new paragraph.","items":[{"id":"a","emoji":"📌","x":20,"y":25,"size":1,"anim":"none"},{"id":"b","emoji":"🔹","x":20,"y":40,"size":1,"anim":"none"},{"id":"c","emoji":"🔹","x":20,"y":50,"size":1,"anim":"none"},{"id":"d","emoji":"📌","x":65,"y":25,"size":3,"anim":"pulse","label":"new paragraph"}]}]},{"type":"check","question":{"type":"true_false","prompt":"You should start a new paragraph when you move to a new idea.","hint":"Each paragraph has one main idea.","answer":[true]}},{"type":"brain_game","game":"memory_match","title":"Writer''s pairs","goal":"Match the pairs.","emojis":["🌙","🪙","📌","📖","🖌️","☂️"]},{"type":"reveal","prompt":"Why is it easier to read a text that has paragraphs?","answer_markdown":"Paragraphs break the text into chunks, so the reader can follow one idea at a time."},{"type":"summary","points":["A simile compares with like or as. A metaphor says something is something else.","Conjunctions join ideas: because, although and while.","An expanded noun phrase paints a clear picture.","A paragraph has one idea and starts with a topic sentence."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 15 questions and takes about 15 minutes."},{"type":"glossary","terms":[{"term":"simile","meaning":"A comparison that uses like or as, such as ''as quick as a cheetah''."},{"term":"like","meaning":"A word used in a simile to compare two things."},{"term":"as","meaning":"A word used in a simile, like in ''as brave as a lion''."},{"term":"metaphor","meaning":"A comparison that says one thing is another thing, such as ''the moon was a coin''."},{"term":"conjunction","meaning":"A word that joins two ideas."},{"term":"because","meaning":"A conjunction that gives a reason."},{"term":"although","meaning":"A conjunction that shows a surprise or a difference."},{"term":"while","meaning":"A conjunction that shows two things happening at the same time."},{"term":"expanded noun phrase","meaning":"A noun with extra describing words, like ''the tall, old tree by the river''."},{"term":"paragraph","meaning":"A group of sentences about one idea."},{"term":"topic sentence","meaning":"The sentence that tells the reader the main idea of a paragraph."}]}],"quiz":{"pass_percent":70,"shuffle_questions":true,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"multiple_choice","prompt":"Which of these is a simile?","hint":"Look for ''like'' or ''as''.","explanation":"A simile compares using like or as.","skill_tag":"figurative.simile","options":[{"id":"a","text":"He is a rocket."},{"id":"b","text":"He ran fast."},{"id":"c","text":"He ran like the wind."}],"answer":["c"]},{"ref":"q2","type":"multiple_choice","prompt":"''The sun is a golden coin.'' What is this?","hint":"It says the sun IS a coin.","explanation":"A metaphor says one thing is another.","skill_tag":"figurative.metaphor","options":[{"id":"a","text":"A simile"},{"id":"b","text":"A metaphor"},{"id":"c","text":"A question"}],"answer":["b"]},{"ref":"q3","type":"multi_select","prompt":"Which of these are similes? Pick all that apply.","hint":"Look for ''as'' or ''like''.","explanation":"Similes use as or like. The others are metaphors.","skill_tag":"figurative.simile","options":[{"id":"a","text":"The sun is a golden coin"},{"id":"b","text":"She is a star"},{"id":"c","text":"ran like the wind"},{"id":"d","text":"as quiet as a mouse"}],"answer":["d","c"]},{"ref":"q4","type":"fill_blank","prompt":"Fill in the gaps.","hint":"Think of two small words.","explanation":"Similes use like or as.","skill_tag":"figurative.simile","points":2,"text":"A simile compares using {b1} or {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"and"},{"id":"b","text":"like"},{"id":"c","text":"but"}]},{"id":"b2","options":[{"id":"a","text":"or"},{"id":"b","text":"as"},{"id":"c","text":"if"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q5","type":"hotspot","prompt":"''The moon was a silver coin.'' Tap the thing being described.","hint":"Which thing is being compared to a coin?","explanation":"The moon is described as a silver coin.","skill_tag":"figurative.metaphor","scene":{"items":[{"id":"h1","emoji":"🌙","label":"moon","x":20,"y":40,"size":3},{"id":"h2","emoji":"🪙","label":"coin","x":50,"y":40,"size":3},{"id":"h3","emoji":"☀️","label":"sun","x":80,"y":40,"size":3},{"id":"h4","emoji":"⭐","label":"star","x":50,"y":80,"size":3}],"show_labels":false},"answer":["h1"]},{"ref":"q6","type":"match","prompt":"Match each joining word to its job.","hint":"Think about each word.","explanation":"Because gives a reason, although shows a surprise and while shows two things at once.","skill_tag":"conjunctions.match","points":2,"left":[{"id":"l1","text":"because"},{"id":"l2","text":"although"},{"id":"l3","text":"while"}],"right":[{"id":"r2","text":"shows a surprise"},{"id":"r1","text":"gives a reason"},{"id":"r3","text":"two things at once"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q7","type":"multiple_choice","prompt":"I wore my coat ___ it was cold.","hint":"It gives the reason.","explanation":"Because gives the reason for wearing a coat.","skill_tag":"conjunctions.because","options":[{"id":"a","text":"although"},{"id":"b","text":"while"},{"id":"c","text":"because"}],"answer":["c"]},{"ref":"q8","type":"multiple_choice","prompt":"___ it was raining, we still had a picnic.","hint":"It shows a surprise.","explanation":"Although shows a surprise: rain, but still a picnic.","skill_tag":"conjunctions.although","options":[{"id":"a","text":"Because"},{"id":"b","text":"Although"},{"id":"c","text":"So"}],"answer":["b"]},{"ref":"q9","type":"multiple_choice","prompt":"Which group of words is an expanded noun phrase?","hint":"It adds extra description.","explanation":"It adds describing words and a place to the noun.","skill_tag":"noun_phrases.expanded","options":[{"id":"a","text":"swam slowly"},{"id":"b","text":"the shimmering lake beside the mountain"},{"id":"c","text":"the lake"}],"answer":["b"]},{"ref":"q10","type":"short_text","prompt":"What do we call a group of sentences about one idea?","hint":"It starts with p.","explanation":"A group of sentences about one idea is a paragraph.","skill_tag":"paragraphs.meaning","answer":{"accepted":["paragraph","a paragraph"]}},{"ref":"q11","type":"true_false","prompt":"A topic sentence tells the reader the main idea of the paragraph.","hint":"It usually comes first.","explanation":"A topic sentence gives the main idea.","skill_tag":"paragraphs.topic","answer":[true]},{"ref":"q12","type":"order","prompt":"Put the sentences in order to make a paragraph.","hint":"Start with the topic sentence.","explanation":"The topic sentence comes first and the ending sentence comes last.","skill_tag":"paragraphs.order","points":2,"items":[{"id":"i2","text":"We wear new clothes."},{"id":"i4","text":"It is a day full of joy."},{"id":"i3","text":"We eat sweet food with family."},{"id":"i1","text":"Eid is my favourite day."}],"answer":["i1","i2","i3","i4"]},{"ref":"q13","type":"slider","prompt":"A story has 3 separate ideas. How many paragraphs would you use?","hint":"One paragraph for each idea.","explanation":"Each idea gets its own paragraph, so 3.","skill_tag":"paragraphs.when","range":{"step":1,"min":1,"max":8,"unit":"paragraphs"},"answer":{"value":3,"tolerance":0}},{"ref":"q14","type":"multiple_choice","prompt":"Which word is an adjective? The shimmering lake was calm.","hint":"It describes the lake.","explanation":"Shimmering describes the lake.","skill_tag":"grammar.adjectives","options":[{"id":"a","text":"was"},{"id":"b","text":"shimmering"},{"id":"c","text":"lake"}],"answer":["b"]},{"ref":"q15","type":"multiple_choice","prompt":"Which is the strongest description?","hint":"Look for the most detail.","explanation":"It adds colour, size and light to make a clear picture.","skill_tag":"writing.description","options":[{"id":"a","text":"The mosque was nice."},{"id":"b","text":"The mosque was big."},{"id":"c","text":"The huge, golden dome of the mosque glowed in the evening light."}],"answer":["c"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT '2ab71d79-3221-5600-a376-b8b9f0865551', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 104, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
