INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('86dff0ae-f991-5197-a12c-9d343261766e', 'a13f4080-fa38-54f3-a3d9-b31226a2e163', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"w2-general-knowledge-class-4","subject":"general-knowledge","title":"Great Thinkers Who Changed the World","summary":"Meet scientists, engineers and teachers from the Islamic Golden Age whose ideas are still used today.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 2: History","learning_objectives":["Say when and where the Islamic Golden Age happened","Name four great thinkers and what they did","Explain how their ideas are used today","Put events on a timeline"],"tags":["week-2","history","inventors","islamic-golden-age"],"curriculum":{"course":"general-knowledge-class-4","semester":1,"week":2}},"blocks":[{"type":"heading","text":"Welcome back, World Explorer!"},{"type":"text","markdown":"Last week you learned about inventions.\n\nThis week we meet some of the people behind big ideas.\n\nLong ago, scientists and teachers in the Muslim world made discoveries that we still use today."},{"type":"image","emoji":"📜","alt":"Ideas from long ago still help us today.","caption":"Ideas from long ago still help us today."},{"type":"heading","text":"Stop 1: The Golden Age"},{"type":"text","markdown":"From about the year 800 to 1200, many great cities in the Muslim world became centres of learning.\n\nThis time is called the **Golden Age**. One famous place was the **House of Wisdom** in Baghdad, where scholars studied, translated and wrote books."},{"type":"explainer","title":"A timeline","scenes":[{"caption":"Around 800: scholars gather in Baghdad.","items":[{"id":"a","emoji":"📚","x":15,"y":50,"size":3,"anim":"pulse"}]},{"caption":"Around 825: Al-Khwarizmi writes about numbers.","items":[{"id":"a","emoji":"📚","x":15,"y":50,"size":2,"anim":"none"},{"id":"b","emoji":"🔢","x":40,"y":50,"size":3,"anim":"grow","label":"algebra"}]},{"caption":"Around 859: Fatima al-Fihri founds a university.","items":[{"id":"a","emoji":"📚","x":10,"y":50,"size":1,"anim":"none"},{"id":"b","emoji":"🔢","x":28,"y":50,"size":2,"anim":"none"},{"id":"c","emoji":"🏛️","x":52,"y":50,"size":3,"anim":"grow","label":"university"}]},{"caption":"Around 1015: Ibn al-Haytham studies light.","items":[{"id":"b","emoji":"🔢","x":15,"y":50,"size":1,"anim":"none"},{"id":"c","emoji":"🏛️","x":33,"y":50,"size":2,"anim":"none"},{"id":"d","emoji":"🔦","x":60,"y":50,"size":3,"anim":"grow","label":"light"}]},{"caption":"In 1206: Al-Jazari writes about machines.","items":[{"id":"c","emoji":"🏛️","x":15,"y":50,"size":1,"anim":"none"},{"id":"d","emoji":"🔦","x":33,"y":50,"size":2,"anim":"none"},{"id":"e","emoji":"⚙️","x":62,"y":50,"size":3,"anim":"spin","label":"machines"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"About when was the Golden Age?","hint":"It was a very long time ago.","options":[{"id":"a","text":"Last year"},{"id":"b","text":"From about 800 to 1200"},{"id":"c","text":"Only in 2000"}],"answer":["b"]}},{"type":"heading","text":"Stop 2: Al-Khwarizmi and numbers"},{"type":"text","markdown":"**Al-Khwarizmi** lived in Baghdad around the year 825. He wrote about the numbers we use today and showed how to solve problems step by step.\n\nHis book gave us the word **algebra**. The word **algorithm** also comes from his name. An algorithm is a list of steps, like the ones in computer programs."},{"type":"image","emoji":"🔢🧮","alt":"The numbers we use today were spread around the world partly through books like Al-Khwarizmi''s.","caption":"The numbers we use today were spread around the world partly through books like Al-Khwarizmi''s."},{"type":"check","question":{"type":"multiple_choice","prompt":"What do we call a list of steps to solve a problem, a word that comes from Al-Khwarizmi''s name?","hint":"You used this word in Computing.","options":[{"id":"a","text":"Telescope"},{"id":"b","text":"Algorithm"},{"id":"c","text":"Compass"}],"answer":["b"]}},{"type":"heading","text":"Stop 3: Ibn al-Haytham and light"},{"type":"text","markdown":"**Ibn al-Haytham** lived in Egypt around the year 1000. He did experiments to find out how we see.\n\nHe showed that we see because light bounces off things and into our eyes. He also studied how a dark room with a tiny hole makes an upside-down picture, called a **camera obscura**."},{"type":"explainer","title":"How we see","scenes":[{"caption":"Light shines from the Sun onto an apple.","items":[{"id":"sun","emoji":"☀️","x":15,"y":20,"size":3,"anim":"pulse"},{"id":"ap","emoji":"🍎","x":50,"y":60,"size":3,"anim":"none"}]},{"caption":"The light bounces off the apple.","items":[{"id":"sun","emoji":"☀️","x":15,"y":20,"size":3,"anim":"none"},{"id":"ap","emoji":"🍎","x":50,"y":60,"size":3,"anim":"none"},{"id":"l","emoji":"✨","x":62,"y":45,"size":2,"anim":"float"}]},{"caption":"It travels into your eye. That is how you see the apple.","items":[{"id":"sun","emoji":"☀️","x":15,"y":20,"size":3,"anim":"none"},{"id":"ap","emoji":"🍎","x":20,"y":60,"size":3,"anim":"none"},{"id":"l","emoji":"✨","x":55,"y":55,"size":2,"anim":"float"},{"id":"eye","emoji":"👁️","x":85,"y":60,"size":3,"anim":"pulse"}]}]},{"type":"check","question":{"type":"true_false","prompt":"Ibn al-Haytham showed that light bounces off objects into our eyes.","hint":"Think about the apple.","answer":[true]}},{"type":"heading","text":"Stop 4: Fatima al-Fihri and Al-Jazari"},{"type":"text","markdown":"**Fatima al-Fihri** started a school in Fez, in Morocco, around the year 859. It became the University of al-Qarawiyyin, one of the oldest universities that is still open.\n\n**Al-Jazari** was an engineer who lived around 1200. He built clever machines like a water clock shaped like an elephant, and he wrote a book with drawings of how they worked."},{"type":"image","emoji":"🏛️🐘⏲️","alt":"A university, an elephant water clock and a machine: ideas that Fatima al-Fihri and Al-Jazari gave us.","caption":"A university, an elephant water clock and a machine: ideas that Fatima al-Fihri and Al-Jazari gave us."},{"type":"check","question":{"type":"multiple_choice","prompt":"Who started the school in Fez that became the University of al-Qarawiyyin?","hint":"She shares a name with your sister.","options":[{"id":"a","text":"Al-Jazari"},{"id":"b","text":"Fatima al-Fihri"},{"id":"c","text":"Al-Khwarizmi"}],"answer":["b"]}},{"type":"activity","title":"Thinker of the day","materials":["Paper and pencil"],"instructions":["Choose one great thinker from today.","Draw them and write one fact about them.","Say how their idea helps us today."]},{"type":"brain_game","game":"memory_match","title":"Golden Age pairs","goal":"Find the matching pairs.","emojis":["📚","🔢","🏛️","🔦","⚙️","🐘"]},{"type":"reveal","prompt":"Why do you think it matters to write ideas in books?","answer_markdown":"Books let people share ideas across places and across time, so others can learn and improve them."},{"type":"summary","points":["The Golden Age was a time of learning in the Muslim world, from about 800 to 1200.","Al-Khwarizmi gave us algebra and the word algorithm.","Ibn al-Haytham explained how we see.","Fatima al-Fihri founded a university and Al-Jazari built clever machines."]},{"type":"callout","style":"tip","markdown":"Ready for the quiz? It has 15 questions and takes about 15 minutes."},{"type":"glossary","terms":[{"term":"Golden Age","meaning":"A time, from about 800 to 1200, when learning and science flourished in the Muslim world."},{"term":"House of Wisdom","meaning":"A famous place of learning in Baghdad where scholars studied, translated and wrote books."},{"term":"Al-Khwarizmi","meaning":"A scholar in Baghdad who wrote about numbers and gave us the word algebra."},{"term":"algebra","meaning":"A kind of maths that uses letters and rules to solve problems."},{"term":"algorithm","meaning":"A list of steps to solve a problem. The word comes from Al-Khwarizmi''s name."},{"term":"Ibn al-Haytham","meaning":"A scientist who showed how we see, using experiments with light."},{"term":"camera obscura","meaning":"A dark room or box with a tiny hole that makes an upside-down picture."},{"term":"Fatima al-Fihri","meaning":"A woman who founded a school in Fez, Morocco, that became a university."},{"term":"Al-Jazari","meaning":"An engineer who built clever machines and wrote a book about how they worked."}]}],"quiz":{"pass_percent":70,"shuffle_questions":true,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"multiple_choice","prompt":"When was the Golden Age of learning in the Muslim world?","hint":"It was around a thousand years ago.","explanation":"The Golden Age was from about 800 to 1200.","skill_tag":"history.golden_age","options":[{"id":"a","text":"About 1900 to 2000"},{"id":"b","text":"About 100 to 200"},{"id":"c","text":"Last century"},{"id":"d","text":"About 800 to 1200"}],"answer":["d"]},{"ref":"q2","type":"multiple_choice","prompt":"In which city was the House of Wisdom?","hint":"It begins with B.","explanation":"The House of Wisdom was in Baghdad.","skill_tag":"history.house_of_wisdom","options":[{"id":"a","text":"Tokyo"},{"id":"b","text":"Lahore"},{"id":"c","text":"Paris"},{"id":"d","text":"Baghdad"}],"answer":["d"]},{"ref":"q3","type":"match","prompt":"Match each person to what they are known for.","hint":"Think of the pictures from the lesson.","explanation":"Al-Khwarizmi is known for algebra, Ibn al-Haytham for how we see and Al-Jazari for machines.","skill_tag":"history.people","points":2,"left":[{"id":"l1","text":"Al-Khwarizmi"},{"id":"l2","text":"Ibn al-Haytham"},{"id":"l3","text":"Al-Jazari"}],"right":[{"id":"r3","text":"Clever machines"},{"id":"r1","text":"Algebra"},{"id":"r2","text":"How we see"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q4","type":"hotspot","prompt":"Tap the person who founded a school in Fez.","hint":"She started a university.","explanation":"Fatima al-Fihri founded the school in Fez.","skill_tag":"history.people","scene":{"items":[{"id":"h1","emoji":"👩‍🏫","label":"Fatima al-Fihri","x":20,"y":50,"size":3},{"id":"h2","emoji":"🧮","label":"Al-Khwarizmi","x":50,"y":50,"size":3},{"id":"h3","emoji":"🔦","label":"Ibn al-Haytham","x":80,"y":50,"size":3}],"show_labels":true},"answer":["h1"]},{"ref":"q5","type":"order","prompt":"Put these in order, earliest first.","hint":"Use the dates.","explanation":"825, then 859, then about 1015, then 1206.","skill_tag":"history.timeline","points":2,"items":[{"id":"i3","text":"Ibn al-Haytham studies light (about 1015)"},{"id":"i4","text":"Al-Jazari writes his book (1206)"},{"id":"i2","text":"Fatima al-Fihri founds a school (about 859)"},{"id":"i1","text":"Al-Khwarizmi writes about numbers (about 825)"}],"answer":["i1","i2","i3","i4"]},{"ref":"q6","type":"fill_blank","prompt":"Fill in the gaps.","hint":"Think of computing.","explanation":"Algorithm comes from Al-Khwarizmi''s name. It is a list of steps.","skill_tag":"history.algorithm","points":2,"text":"The word {b1} comes from the name of Al-Khwarizmi. It means a list of {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"compass"},{"id":"b","text":"algorithm"},{"id":"c","text":"telescope"}]},{"id":"b2","options":[{"id":"a","text":"pictures"},{"id":"b","text":"steps"},{"id":"c","text":"stars"}]}],"answer":{"b1":"b","b2":"b"}},{"ref":"q7","type":"true_false","prompt":"Ibn al-Haytham showed that light bounces off objects and goes into our eyes.","hint":"Think about seeing an apple.","explanation":"He explained that we see because light enters our eyes.","skill_tag":"science.light","answer":[true]},{"ref":"q8","type":"slider","prompt":"Al-Khwarizmi wrote about numbers around the year 825. Fatima al-Fihri founded her school around the year 859. About how many years later was that?","hint":"Take away 825 from 859.","explanation":"859 - 825 = 34 years.","skill_tag":"history.timeline","range":{"step":1,"min":0,"max":100,"unit":"years"},"answer":{"value":34,"tolerance":4}},{"ref":"q9","type":"multi_select","prompt":"Which of these did Al-Jazari work on? Pick all that apply.","hint":"Think of the elephant.","explanation":"Al-Jazari built machines such as an elephant-shaped water clock.","skill_tag":"history.al_jazari","options":[{"id":"a","text":"The telephone"},{"id":"b","text":"The light bulb"},{"id":"c","text":"A water clock"},{"id":"d","text":"Clever machines"}],"answer":["d","c"]},{"ref":"q10","type":"multiple_choice","prompt":"A camera obscura makes ...","hint":"A dark room with a tiny hole.","explanation":"A camera obscura makes an upside-down picture.","skill_tag":"science.light","options":[{"id":"a","text":"A cold wind"},{"id":"b","text":"A new planet"},{"id":"c","text":"A loud sound"},{"id":"d","text":"An upside-down picture"}],"answer":["d"]},{"ref":"q11","type":"multiple_choice","prompt":"In which country is the city of Fez?","hint":"It is in Africa.","explanation":"Fez is in Morocco.","skill_tag":"history.fatima","options":[{"id":"a","text":"Pakistan"},{"id":"b","text":"France"},{"id":"c","text":"Japan"},{"id":"d","text":"Morocco"}],"answer":["d"]},{"ref":"q12","type":"multiple_choice","prompt":"Which word comes from Al-Khwarizmi''s book?","hint":"It is a kind of maths.","explanation":"Algebra comes from the title of Al-Khwarizmi''s book.","skill_tag":"history.algebra","options":[{"id":"a","text":"Atlas"},{"id":"b","text":"Allergy"},{"id":"c","text":"Alphabet"},{"id":"d","text":"Algebra"}],"answer":["d"]},{"ref":"q13","type":"short_text","prompt":"What was the famous place of learning in Baghdad called? (the House of ...)","hint":"It means being very clever.","explanation":"It was called the House of Wisdom.","skill_tag":"history.house_of_wisdom","answer":{"accepted":["Wisdom","the House of Wisdom","House of Wisdom"]}},{"ref":"q14","type":"multiple_choice","prompt":"Why do we still use ideas from the Golden Age?","hint":"Think about how books help.","explanation":"The ideas were written in books and shared, so people kept learning from them.","skill_tag":"history.legacy","options":[{"id":"a","text":"They were secret"},{"id":"b","text":"They were forgotten"},{"id":"c","text":"They were never written down"},{"id":"d","text":"They were written in books and shared across the world"}],"answer":["d"]},{"ref":"q15","type":"multiple_choice","prompt":"What does an algorithm help us to do?","hint":"It is a list of steps.","explanation":"An algorithm is a list of steps to solve a problem.","skill_tag":"history.algorithm","options":[{"id":"a","text":"Find the capital city"},{"id":"b","text":"Plant a seed"},{"id":"c","text":"Draw a map"},{"id":"d","text":"Solve a problem step by step"}],"answer":["d"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT '05cb437e-e698-52d0-a456-b8341f7274fe', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 106, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
