WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"w2-maths-class-1","subject":"maths","title":"Number Bonds and Doubles","summary":"Find the pairs that make 10, use them to add quickly, and learn doubles and fact families.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 2: Number bonds","learning_objectives":["Know pairs of numbers that make 10","Use number bonds to add quickly","Double numbers up to 10","See how adding and taking away are linked"],"tags":["week-2","number-bonds","doubles"],"curriculum":{"course":"maths-class-1","semester":1,"week":2}},"blocks":[{"type":"heading","text":"Welcome back, Maths Explorer!"},{"type":"text","markdown":"Last week you counted, added and took away.\n\nThis week we find quick tricks to make adding easier.\n\nLet''s play with pairs of numbers!"},{"type":"image","emoji":"🧩","alt":"Numbers fit together like puzzle pieces.","caption":"Numbers fit together like puzzle pieces."},{"type":"heading","text":"Stop 1: Pairs that make 10"},{"type":"text","markdown":"A **number bond** is a pair of numbers that fit together to make a bigger number.\n\n7 and 3 make 10. So 7 and 3 are a bond to 10."},{"type":"explainer","title":"7 and 3 make 10","scenes":[{"caption":"Here are 7 red counters.","items":[{"id":"r1","emoji":"🔴","x":10,"y":35,"size":2,"anim":"none"},{"id":"r2","emoji":"🔴","x":20,"y":35,"size":2,"anim":"none"},{"id":"r3","emoji":"🔴","x":30,"y":35,"size":2,"anim":"none"},{"id":"r4","emoji":"🔴","x":40,"y":35,"size":2,"anim":"none"},{"id":"r5","emoji":"🔴","x":50,"y":35,"size":2,"anim":"none"},{"id":"r6","emoji":"🔴","x":60,"y":35,"size":2,"anim":"none"},{"id":"r7","emoji":"🔴","x":70,"y":35,"size":2,"anim":"none"}]},{"caption":"We need 3 more to make 10.","items":[{"id":"r1","emoji":"🔴","x":10,"y":35,"size":2,"anim":"none"},{"id":"r2","emoji":"🔴","x":20,"y":35,"size":2,"anim":"none"},{"id":"r3","emoji":"🔴","x":30,"y":35,"size":2,"anim":"none"},{"id":"r4","emoji":"🔴","x":40,"y":35,"size":2,"anim":"none"},{"id":"r5","emoji":"🔴","x":50,"y":35,"size":2,"anim":"none"},{"id":"r6","emoji":"🔴","x":60,"y":35,"size":2,"anim":"none"},{"id":"r7","emoji":"🔴","x":70,"y":35,"size":2,"anim":"none"},{"id":"b1","emoji":"🔵","x":20,"y":70,"size":2,"anim":"grow"},{"id":"b2","emoji":"🔵","x":35,"y":70,"size":2,"anim":"grow"},{"id":"b3","emoji":"🔵","x":50,"y":70,"size":2,"anim":"grow"}]},{"caption":"7 and 3 make 10!","items":[{"id":"r1","emoji":"🔴","x":6,"y":50,"size":2,"anim":"none"},{"id":"r2","emoji":"🔴","x":16,"y":50,"size":2,"anim":"none"},{"id":"r3","emoji":"🔴","x":26,"y":50,"size":2,"anim":"none"},{"id":"r4","emoji":"🔴","x":36,"y":50,"size":2,"anim":"none"},{"id":"r5","emoji":"🔴","x":46,"y":50,"size":2,"anim":"none"},{"id":"r6","emoji":"🔴","x":56,"y":50,"size":2,"anim":"none"},{"id":"r7","emoji":"🔴","x":66,"y":50,"size":2,"anim":"none"},{"id":"b1","emoji":"🔵","x":72,"y":50,"size":2,"anim":"none"},{"id":"b2","emoji":"🔵","x":82,"y":50,"size":2,"anim":"none"},{"id":"b3","emoji":"🔵","x":92,"y":50,"size":2,"anim":"none"},{"emoji":"🔟","x":50,"y":15,"size":3,"anim":"pulse"}]}]},{"type":"check","question":{"type":"number","prompt":"3 + ? = 10. What number is missing?","hint":"Count on from 3 to 10.","answer":{"value":7,"tolerance":0}}},{"type":"manipulative","title":"Make 10","goal":"Share the 10 stars between two baskets. Which pairs can you make? Try 6 and 4, then 8 and 2.","emoji":"⭐","count":10,"zones":["Basket A","Basket B"]},{"type":"chart","kind":"number_line","title":"Bonds to 10 on a line","from":0,"to":10,"step":1,"marks":[4,10],"caption":"From 4, hop 6 steps to reach 10. So 4 and 6 are a bond to 10."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which pair makes 10?","hint":"Add each pair.","options":[{"id":"a","text":"5 and 4"},{"id":"b","text":"6 and 4"},{"id":"c","text":"8 and 3"}],"answer":["b"]}},{"type":"heading","text":"Stop 2: Make 10 to add"},{"type":"text","markdown":"Bonds help us add big numbers. For 8 + 5, split the 5 into 2 and 3.\n\n8 and 2 make **ten**. Then add the 3 that is left. The answer is 13."},{"type":"explainer","title":"8 + 5 by making ten","scenes":[{"caption":"Start with 8 and 5.","items":[{"id":"a1","emoji":"🟠","x":8,"y":30,"size":2,"anim":"none"},{"id":"a2","emoji":"🟠","x":16,"y":30,"size":2,"anim":"none"},{"id":"a3","emoji":"🟠","x":24,"y":30,"size":2,"anim":"none"},{"id":"a4","emoji":"🟠","x":32,"y":30,"size":2,"anim":"none"},{"id":"a5","emoji":"🟠","x":40,"y":30,"size":2,"anim":"none"},{"id":"a6","emoji":"🟠","x":48,"y":30,"size":2,"anim":"none"},{"id":"a7","emoji":"🟠","x":56,"y":30,"size":2,"anim":"none"},{"id":"a8","emoji":"🟠","x":64,"y":30,"size":2,"anim":"none"},{"id":"b1","emoji":"🟣","x":20,"y":70,"size":2,"anim":"none"},{"id":"b2","emoji":"🟣","x":36,"y":70,"size":2,"anim":"none"},{"id":"b3","emoji":"🟣","x":52,"y":70,"size":2,"anim":"none"},{"id":"b4","emoji":"🟣","x":68,"y":70,"size":2,"anim":"none"},{"id":"b5","emoji":"🟣","x":84,"y":70,"size":2,"anim":"none"}]},{"caption":"Move 2 purple counters to fill the ten.","items":[{"id":"a1","emoji":"🟠","x":8,"y":30,"size":2,"anim":"none"},{"id":"a2","emoji":"🟠","x":16,"y":30,"size":2,"anim":"none"},{"id":"a3","emoji":"🟠","x":24,"y":30,"size":2,"anim":"none"},{"id":"a4","emoji":"🟠","x":32,"y":30,"size":2,"anim":"none"},{"id":"a5","emoji":"🟠","x":40,"y":30,"size":2,"anim":"none"},{"id":"a6","emoji":"🟠","x":48,"y":30,"size":2,"anim":"none"},{"id":"a7","emoji":"🟠","x":56,"y":30,"size":2,"anim":"none"},{"id":"a8","emoji":"🟠","x":64,"y":30,"size":2,"anim":"none"},{"id":"b1","emoji":"🟣","x":76,"y":30,"size":2,"anim":"bounce"},{"id":"b2","emoji":"🟣","x":90,"y":30,"size":2,"anim":"bounce"},{"id":"b3","emoji":"🟣","x":20,"y":70,"size":2,"anim":"none"},{"id":"b4","emoji":"🟣","x":40,"y":70,"size":2,"anim":"none"},{"id":"b5","emoji":"🟣","x":60,"y":70,"size":2,"anim":"none"}]},{"caption":"A full ten, plus 3 more is 13.","items":[{"id":"a1","emoji":"🟠","x":8,"y":30,"size":2,"anim":"none"},{"id":"a2","emoji":"🟠","x":16,"y":30,"size":2,"anim":"none"},{"id":"a3","emoji":"🟠","x":24,"y":30,"size":2,"anim":"none"},{"id":"a4","emoji":"🟠","x":32,"y":30,"size":2,"anim":"none"},{"id":"a5","emoji":"🟠","x":40,"y":30,"size":2,"anim":"none"},{"id":"a6","emoji":"🟠","x":48,"y":30,"size":2,"anim":"none"},{"id":"a7","emoji":"🟠","x":56,"y":30,"size":2,"anim":"none"},{"id":"a8","emoji":"🟠","x":64,"y":30,"size":2,"anim":"none"},{"id":"b1","emoji":"🟣","x":76,"y":30,"size":2,"anim":"none"},{"id":"b2","emoji":"🟣","x":90,"y":30,"size":2,"anim":"none"},{"id":"b3","emoji":"🟣","x":30,"y":70,"size":2,"anim":"none"},{"id":"b4","emoji":"🟣","x":50,"y":70,"size":2,"anim":"none"},{"id":"b5","emoji":"🟣","x":70,"y":70,"size":2,"anim":"none"},{"emoji":"1️⃣3️⃣","x":88,"y":70,"size":3,"anim":"pulse"}]}]},{"type":"check","question":{"type":"number","prompt":"What is 9 + 4? Make ten first: 9 and 1 make 10.","hint":"Ten and 3 more.","answer":{"value":13,"tolerance":0}}},{"type":"check","question":{"type":"number","prompt":"What is 7 + 5?","hint":"7 and 3 make 10. Then add 2 more.","answer":{"value":12,"tolerance":0}}},{"type":"heading","text":"Stop 3: Doubles"},{"type":"text","markdown":"A **double** is adding the same number twice. Double 4 is 4 + 4 = 8.\n\nDoubles are like a mirror: you see the same picture on both sides."},{"type":"explainer","title":"Double 4","scenes":[{"caption":"Here are 4 ladybirds.","items":[{"id":"l1","emoji":"🐞","x":10,"y":50,"size":2,"anim":"none"},{"id":"l2","emoji":"🐞","x":20,"y":50,"size":2,"anim":"none"},{"id":"l3","emoji":"🐞","x":30,"y":50,"size":2,"anim":"none"},{"id":"l4","emoji":"🐞","x":40,"y":50,"size":2,"anim":"none"}]},{"caption":"Make a mirror copy with 4 more.","items":[{"id":"l1","emoji":"🐞","x":10,"y":50,"size":2,"anim":"none"},{"id":"l2","emoji":"🐞","x":20,"y":50,"size":2,"anim":"none"},{"id":"l3","emoji":"🐞","x":30,"y":50,"size":2,"anim":"none"},{"id":"l4","emoji":"🐞","x":40,"y":50,"size":2,"anim":"none"},{"id":"m1","emoji":"🐞","x":60,"y":50,"size":2,"anim":"grow"},{"id":"m2","emoji":"🐞","x":70,"y":50,"size":2,"anim":"grow"},{"id":"m3","emoji":"🐞","x":80,"y":50,"size":2,"anim":"grow"},{"id":"m4","emoji":"🐞","x":90,"y":50,"size":2,"anim":"grow"}]},{"caption":"4 and 4 make 8. Double 4 is 8!","items":[{"id":"l1","emoji":"🐞","x":10,"y":50,"size":2,"anim":"none"},{"id":"l2","emoji":"🐞","x":20,"y":50,"size":2,"anim":"none"},{"id":"l3","emoji":"🐞","x":30,"y":50,"size":2,"anim":"none"},{"id":"l4","emoji":"🐞","x":40,"y":50,"size":2,"anim":"none"},{"id":"m1","emoji":"🐞","x":60,"y":50,"size":2,"anim":"none"},{"id":"m2","emoji":"🐞","x":70,"y":50,"size":2,"anim":"none"},{"id":"m3","emoji":"🐞","x":80,"y":50,"size":2,"anim":"none"},{"id":"m4","emoji":"🐞","x":90,"y":50,"size":2,"anim":"none"},{"emoji":"8️⃣","x":50,"y":18,"size":3,"anim":"pulse"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"What is double 6?","hint":"Add 6 and 6.","options":[{"id":"a","text":"10"},{"id":"b","text":"6"},{"id":"c","text":"14"},{"id":"d","text":"12"}],"answer":["d"]}},{"type":"text","markdown":"Near doubles help too. 6 + 7 is double 6, plus 1 more. That is 13."},{"type":"check","question":{"type":"number","prompt":"What is double 5?","hint":"5 + 5.","answer":{"value":10,"tolerance":0}}},{"type":"heading","text":"Stop 4: Fact families"},{"type":"text","markdown":"Adding and taking away are linked. One set of numbers gives a **fact family**.\n\n7, 3 and 10 give four facts: 7 + 3 = 10, 3 + 7 = 10, 10 - 3 = 7 and 10 - 7 = 3."},{"type":"image","emoji":"🔺","alt":"A fact family triangle: 10 at the top, and 7 and 3 at the bottom corners.","caption":"A fact family triangle: 10 at the top, and 7 and 3 at the bottom corners."},{"type":"check","question":{"type":"number","prompt":"7 + 3 = 10, so 10 - 3 = ?","hint":"Taking away undoes adding.","answer":{"value":7,"tolerance":0}}},{"type":"reveal","prompt":"Can you write the four facts for 6, 4 and 10?","answer_markdown":"6 + 4 = 10, 4 + 6 = 10, 10 - 4 = 6 and 10 - 6 = 4."},{"type":"brain_game","game":"remember_order","title":"Copy the counters","goal":"Watch the order of the lights, then copy it. It gets longer each time!","emojis":["🔴","🔵","🟡","🟢"]},{"type":"summary","points":["A number bond is a pair that makes a number, like 7 and 3 make 10.","Make ten first to add quickly.","A double is a number added to itself.","Adding and taking away are linked in a fact family."]},{"type":"callout","style":"tip","markdown":"Ready for the quiz? It has 15 questions and takes about 15 minutes. Use the tricks you learned today!"},{"type":"glossary","terms":[{"term":"number bond","meaning":"A pair of numbers that fit together to make a bigger number, like 7 and 3 make 10."},{"term":"ten","meaning":"The number 10. A full row of ten counters."},{"term":"double","meaning":"Adding the same number twice. Double 4 is 4 + 4 = 8."},{"term":"fact family","meaning":"A set of adding and taking away facts that use the same three numbers."}]}],"quiz":{"pass_percent":70,"shuffle_questions":true,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"number","prompt":"6 + ? = 10. What number is missing?","hint":"Count on from 6 to 10.","explanation":"6 and 4 make 10.","skill_tag":"bonds.to_10","answer":{"value":4,"tolerance":0}},{"ref":"q2","type":"multiple_choice","prompt":"Which pair of numbers makes 10?","hint":"Add each pair to check.","explanation":"2 + 8 = 10.","skill_tag":"bonds.to_10","options":[{"id":"a","text":"3 and 6"},{"id":"b","text":"9 and 2"},{"id":"c","text":"4 and 5"},{"id":"d","text":"2 and 8"}],"answer":["d"]},{"ref":"q3","type":"number","prompt":"What is 9 + 6?","hint":"Take 1 from the 6 to make 10 with the 9.","explanation":"9 and 1 make 10, and 5 more makes 15.","skill_tag":"bonds.make_ten","answer":{"value":15,"tolerance":0}},{"ref":"q4","type":"number","prompt":"What is 8 + 7?","hint":"8 and 2 make ten.","explanation":"8 + 2 = 10, then 5 more is 15.","skill_tag":"bonds.make_ten","answer":{"value":15,"tolerance":0}},{"ref":"q5","type":"multiple_choice","prompt":"What is double 7?","hint":"Add 7 and 7.","explanation":"7 + 7 = 14.","skill_tag":"doubles.recall","options":[{"id":"a","text":"16"},{"id":"b","text":"7"},{"id":"c","text":"12"},{"id":"d","text":"14"}],"answer":["d"]},{"ref":"q6","type":"fill_blank","prompt":"Fill in the gaps about doubles.","hint":"Add each number to itself.","explanation":"5 + 5 = 10 and 8 + 8 = 16.","skill_tag":"doubles.recall","points":2,"text":"Double 5 is {b1} and double 8 is {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"5"},{"id":"b","text":"15"},{"id":"c","text":"10"}]},{"id":"b2","options":[{"id":"a","text":"18"},{"id":"b","text":"16"},{"id":"c","text":"8"}]}],"answer":{"b1":"c","b2":"b"}},{"ref":"q7","type":"slider","prompt":"Slide to show double 9 on the number line.","hint":"9 + 9 is 10 and 8.","explanation":"Double 9 is 18.","skill_tag":"doubles.recall","range":{"step":1,"min":0,"max":20},"answer":{"value":18,"tolerance":0}},{"ref":"q8","type":"true_false","prompt":"Double 6 is 14.","hint":"Say 6 + 6 out loud.","explanation":"Double 6 is 12, not 14.","skill_tag":"doubles.recall","answer":[false]},{"ref":"q9","type":"number","prompt":"6 + 7 is a near double. What is 6 + 7?","hint":"Double 6 and one more.","explanation":"Double 6 is 12 and one more is 13.","skill_tag":"doubles.near","answer":{"value":13,"tolerance":0}},{"ref":"q10","type":"match","prompt":"Match each sum to its answer.","hint":"Work out each sum.","explanation":"4 + 6 = 10, 7 + 8 = 15 and 9 + 9 = 18.","skill_tag":"bonds.match","points":2,"left":[{"id":"l1","text":"4 + 6"},{"id":"l2","text":"7 + 8"},{"id":"l3","text":"9 + 9"}],"right":[{"id":"r3","text":"18"},{"id":"r1","text":"10"},{"id":"r2","text":"15"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q11","type":"order","prompt":"Put the answers in order, smallest first.","hint":"Work out each answer first.","explanation":"The answers are 4, 7, 12 and 18.","skill_tag":"number.order","points":2,"items":[{"id":"i2","text":"3 + 4"},{"id":"i3","text":"6 + 6"},{"id":"i4","text":"9 + 9"},{"id":"i1","text":"2 + 2"}],"answer":["i1","i2","i3","i4"]},{"ref":"q12","type":"multi_select","prompt":"Which of these are doubles? Pick all that apply.","hint":"A double adds the same number twice.","explanation":"3 + 3 and 8 + 8 add the same number twice.","skill_tag":"doubles.recognise","options":[{"id":"a","text":"3 + 4"},{"id":"b","text":"5 + 6"},{"id":"c","text":"8 + 8"},{"id":"d","text":"3 + 3"}],"answer":["d","c"]},{"ref":"q13","type":"hotspot","prompt":"Tap the pair of boxes that show a double.","hint":"Look for two of the same thing.","explanation":"Two apples is 1 + 1, the same picture twice.","skill_tag":"doubles.recognise","scene":{"items":[{"id":"h1","emoji":"🍎🍎","label":"two apples","x":20,"y":30,"size":3},{"id":"h2","emoji":"🍎🍌","label":"an apple and a banana","x":70,"y":30,"size":3},{"id":"h3","emoji":"🍌🍌🍌🍌","label":"four bananas","x":20,"y":70,"size":3},{"id":"h4","emoji":"🍌🍎🍇","label":"three different fruits","x":70,"y":70,"size":3}],"show_labels":false},"answer":["h1"]},{"ref":"q14","type":"number","prompt":"If 4 + 9 = 13, what is 13 - 9?","hint":"Taking away undoes adding.","explanation":"13 take away 9 leaves 4, because 4 + 9 = 13.","skill_tag":"factfamily.subtract","answer":{"value":4,"tolerance":0}},{"ref":"q15","type":"multiple_choice","prompt":"Which fact is in the same family as 6 + 5 = 11?","hint":"The family uses the numbers 5, 6 and 11.","explanation":"11 - 5 = 6 uses the same three numbers as 6 + 5 = 11.","skill_tag":"factfamily.recognise","options":[{"id":"a","text":"11 + 5 = 16"},{"id":"b","text":"5 + 5 = 10"},{"id":"c","text":"6 - 5 = 11"},{"id":"d","text":"11 - 5 = 6"}],"answer":["d"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'af6a265f-35d1-5f3c-a8ff-2a132dce9b52', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 107, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
