INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT '1a02442d-784e-5ba8-ac1c-3ab066821a68' || ':' || json_extract(e.value,'$.ref'), '1a02442d-784e-5ba8-ac1c-3ab066821a68', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) WHEN 'fill_blank' THEN json_object('text', json_extract(e.value,'$.text'), 'blanks', json_extract(e.value,'$.blanks')) WHEN 'hotspot' THEN json_object('scene', json_extract(e.value,'$.scene')) WHEN 'slider' THEN json_object('range', json_extract(e.value,'$.range')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = '72424f28-42f7-510b-ac0f-eaa6d859632e';
INSERT OR IGNORE INTO courses (id, slug, title, description, subject_id, age_band, status) VALUES ('90dc3e3c-b106-51e4-af87-bad3e017e698', 'science-class-4', 'Science (Class 4)', 'Science for Class 4', 'science', '9-10', 'published');
INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('462c3e47-3dac-529e-a9ba-ff314b49f487', '90dc3e3c-b106-51e4-af87-bad3e017e698', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"w2-science-class-4","subject":"science","title":"How Plants Make Food and Grow","summary":"See how plants make food from sunlight, how water travels up the stem, and how plants make new plants.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 2: Plants","learning_objectives":["Describe what plants need to make food","Explain the jobs of the roots, stem, leaves and flower","Describe pollination and how seeds travel","Order the stages of a plant''s life cycle"],"tags":["week-2","plants","photosynthesis"],"curriculum":{"course":"science-class-4","semester":1,"week":2}},"blocks":[{"type":"heading","text":"Welcome back, Scientist!"},{"type":"text","markdown":"Last week you learned that a food chain starts with a producer.\n\nThis week we find out how a plant makes its food.\n\nWe will follow a seed from start to finish."},{"type":"image","emoji":"🌻","alt":"A sunflower follows the sun across the sky. It is a producer!","caption":"A sunflower follows the sun across the sky. It is a producer!"},{"type":"heading","text":"Stop 1: Jobs of the plant parts"},{"type":"text","markdown":"Each part of a plant has a job. **Roots** hold the plant in the soil and take in water. The **stem** holds the plant up and carries water to the leaves.\n\n**Leaves** make food. The **flower** helps the plant make seeds."},{"type":"image","emoji":"🌱🌿🌸","alt":"Roots below the ground, a stem and leaves above, and a flower on top.","caption":"Roots below the ground, a stem and leaves above, and a flower on top."},{"type":"explainer","title":"Water travels up the stem","scenes":[{"caption":"Water is in the soil.","items":[{"id":"soil","emoji":"🟤","x":50,"y":88,"size":3,"anim":"none"},{"id":"w","emoji":"💧","x":40,"y":85,"size":2,"anim":"none"}]},{"caption":"The roots take in the water.","items":[{"id":"soil","emoji":"🟤","x":50,"y":88,"size":3,"anim":"none"},{"id":"w","emoji":"💧","x":45,"y":75,"size":2,"anim":"float"},{"id":"p","emoji":"🌿","x":50,"y":55,"size":3,"anim":"none"}]},{"caption":"The water moves up the stem to the leaves.","items":[{"id":"soil","emoji":"🟤","x":50,"y":88,"size":3,"anim":"none"},{"id":"w","emoji":"💧","x":50,"y":50,"size":2,"anim":"float"},{"id":"p","emoji":"🌿","x":50,"y":55,"size":3,"anim":"none"}]},{"caption":"The leaves use the water to make food.","items":[{"id":"soil","emoji":"🟤","x":50,"y":88,"size":3,"anim":"none"},{"id":"w","emoji":"💧","x":55,"y":30,"size":2,"anim":"pulse"},{"id":"p","emoji":"🌿","x":50,"y":55,"size":3,"anim":"none"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which part of a plant carries water up to the leaves?","hint":"It holds the plant up too.","options":[{"id":"a","text":"The flower"},{"id":"b","text":"The stem"},{"id":"c","text":"The seed"}],"answer":["b"]}},{"type":"activity","title":"Colourful celery","materials":["A stick of celery with leaves","A glass of water","Red or blue food colouring"],"instructions":["Add a few drops of food colouring to the water.","Stand the celery in the glass.","Look again after a few hours. Where did the colour go?"]},{"type":"heading","text":"Stop 2: Making food in the leaves"},{"type":"text","markdown":"Plants make their own food using sunlight. This is called **photosynthesis**.\n\nThe leaves take in **carbon dioxide** from the air. The roots take in water. Sunlight gives the energy.\n\nThe plant makes sugar, its food, and gives out **oxygen**, the gas we breathe."},{"type":"explainer","title":"Photosynthesis","scenes":[{"caption":"A leaf in the sunlight.","items":[{"id":"leaf","emoji":"🍃","x":50,"y":55,"size":3,"anim":"none"},{"id":"sun","emoji":"☀️","x":80,"y":15,"size":3,"anim":"pulse"}]},{"caption":"The leaf takes in carbon dioxide and water.","items":[{"id":"leaf","emoji":"🍃","x":50,"y":55,"size":3,"anim":"none"},{"id":"sun","emoji":"☀️","x":80,"y":15,"size":3,"anim":"pulse"},{"id":"co","emoji":"💨","x":15,"y":55,"size":2,"anim":"float","label":"carbon dioxide"},{"id":"w","emoji":"💧","x":50,"y":90,"size":2,"anim":"float","label":"water"}]},{"caption":"It makes sugar for food and gives out oxygen.","items":[{"id":"leaf","emoji":"🍃","x":50,"y":55,"size":3,"anim":"none"},{"id":"sun","emoji":"☀️","x":80,"y":15,"size":3,"anim":"pulse"},{"id":"su","emoji":"🍬","x":25,"y":25,"size":2,"anim":"grow","label":"sugar"},{"id":"ox","emoji":"🫧","x":85,"y":60,"size":2,"anim":"float","label":"oxygen"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"What do plants use to make food? Pick the best answer.","hint":"Look at what the leaf took in.","options":[{"id":"a","text":"Soil, wind and sugar"},{"id":"b","text":"Oxygen and rain"},{"id":"c","text":"Only soil"},{"id":"d","text":"Sunlight, water and carbon dioxide"}],"answer":["d"]}},{"type":"check","question":{"type":"true_false","prompt":"Plants give out oxygen when they make food.","hint":"The bubbles in the picture.","answer":[true]}},{"type":"callout","style":"fun_fact","markdown":"Plants make the oxygen we breathe, and the food at the start of nearly every food chain."},{"type":"heading","text":"Stop 3: Pollination and seeds"},{"type":"text","markdown":"A flower makes seeds. First, **pollen** must move from one flower to another. This is **pollination**.\n\nBees and butterflies visit flowers for sweet nectar. Pollen sticks to them and they carry it to the next flower."},{"type":"explainer","title":"A bee pollinates a flower","scenes":[{"caption":"A bee visits a flower.","items":[{"id":"f1","emoji":"🌼","x":25,"y":65,"size":3,"anim":"none"},{"id":"bee","emoji":"🐝","x":25,"y":30,"size":3,"anim":"float"},{"id":"f2","emoji":"🌸","x":75,"y":65,"size":3,"anim":"none"}]},{"caption":"Pollen sticks to the bee.","items":[{"id":"f1","emoji":"🌼","x":25,"y":65,"size":3,"anim":"none"},{"id":"bee","emoji":"🐝","x":40,"y":50,"size":3,"anim":"bounce","label":"pollen"},{"id":"f2","emoji":"🌸","x":75,"y":65,"size":3,"anim":"none"}]},{"caption":"The bee carries the pollen to another flower.","items":[{"id":"f1","emoji":"🌼","x":25,"y":65,"size":3,"anim":"none"},{"id":"bee","emoji":"🐝","x":75,"y":40,"size":3,"anim":"bounce","label":"pollen"},{"id":"f2","emoji":"🌸","x":75,"y":65,"size":3,"anim":"pulse"}]}]},{"type":"text","markdown":"Then the flower grows seeds. A **seed** can grow into a new plant if it gets water, warmth and air.\n\nSeeds travel far from the parent plant so they have room to grow. This is **seed dispersal**."},{"type":"image","emoji":"🌬️🌰🐿️🌊","alt":"Seeds can travel on the wind, in animals'' fur or tummies, or on water, like a coconut.","caption":"Seeds can travel on the wind, in animals'' fur or tummies, or on water, like a coconut."},{"type":"check","question":{"type":"multiple_choice","prompt":"A dandelion seed has fluffy parts that float. How does it travel?","hint":"Think of blowing a dandelion clock.","options":[{"id":"a","text":"In an animal''s tummy"},{"id":"b","text":"On the wind"},{"id":"c","text":"On water"}],"answer":["b"]}},{"type":"brain_game","game":"remember_order","title":"Seed journey","goal":"Watch the order of the lights and copy it.","emojis":["🌰","💧","☀️","🌱"]},{"type":"heading","text":"Stop 4: The life cycle of a plant"},{"type":"text","markdown":"A plant has a **life cycle**. A seed starts to grow, which is called **germination**.\n\nA root grows down and a shoot grows up. The young plant is a seedling. It grows into an adult plant that flowers and makes new seeds."},{"type":"explainer","title":"A plant''s life cycle","scenes":[{"caption":"1. A seed in the soil.","items":[{"id":"p","emoji":"🌰","x":50,"y":70,"size":3,"anim":"none"}]},{"caption":"2. The seed germinates. A root and shoot grow.","items":[{"id":"p","emoji":"🌱","x":50,"y":65,"size":3,"anim":"grow"}]},{"caption":"3. It grows into an adult plant.","items":[{"id":"p","emoji":"🌿","x":50,"y":60,"size":3,"anim":"grow"}]},{"caption":"4. The plant flowers and makes new seeds.","items":[{"id":"p","emoji":"🌻","x":50,"y":55,"size":3,"anim":"grow"},{"id":"s","emoji":"🌰","x":80,"y":80,"size":2,"anim":"bounce"}]}]},{"type":"manipulative","title":"Plant the seeds","goal":"Put 6 seeds in the pot that has water and sun. Put 4 seeds in the dark cupboard. Which seeds do you think will grow best?","emoji":"🌰","count":10,"zones":["Sunny, watered pot","Dark cupboard"]},{"type":"check","question":{"type":"multi_select","prompt":"Which two things does a seed need to germinate? Pick all that apply.","hint":"Think of planting in spring.","options":[{"id":"a","text":"Warmth"},{"id":"b","text":"Loud music"},{"id":"c","text":"A magnet"},{"id":"d","text":"Water"}],"answer":["d","a"]}},{"type":"reveal","prompt":"Why do plants make so many seeds?","answer_markdown":"Many seeds never land in a good spot. Making lots of seeds gives some a chance to grow."},{"type":"summary","points":["Roots take in water, the stem carries it, leaves make food and flowers make seeds.","Photosynthesis uses sunlight, water and carbon dioxide to make sugar and oxygen.","Pollination moves pollen between flowers, then seeds form.","Seeds travel, germinate and grow into new plants."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 15 questions and takes about 15 minutes."},{"type":"glossary","terms":[{"term":"roots","meaning":"The parts of a plant under the ground. They hold it in place and take in water."},{"term":"stem","meaning":"The part of a plant that holds it up and carries water to the leaves."},{"term":"leaves","meaning":"The parts of a plant that make food using sunlight."},{"term":"flower","meaning":"The part of a plant that helps it make seeds."},{"term":"photosynthesis","meaning":"How a plant makes food from sunlight, water and carbon dioxide."},{"term":"carbon dioxide","meaning":"A gas in the air that plants take in to make food."},{"term":"oxygen","meaning":"A gas that plants give out and that animals and people breathe in."},{"term":"pollen","meaning":"Tiny yellow dust made by flowers. It is needed to make seeds."},{"term":"pollination","meaning":"When pollen is moved from one flower to another so seeds can form."},{"term":"seed","meaning":"The part of a plant that can grow into a new plant."},{"term":"seed dispersal","meaning":"How seeds are spread far away from the parent plant."},{"term":"life cycle","meaning":"The stages of a living thing''s life, from start to start again."},{"term":"germination","meaning":"When a seed starts to grow."}]}],"quiz":{"pass_percent":70,"shuffle_questions":true,"shuffle_options":true,"max_attempts":null,"questions":[{"ref":"q1","type":"match","prompt":"Match each plant part to its job.","hint":"Think about where each part is.","explanation":"Roots take in water, the stem carries it and leaves make food.","skill_tag":"plants.parts","points":2,"left":[{"id":"l1","text":"Roots"},{"id":"l2","text":"Stem"},{"id":"l3","text":"Leaves"}],"right":[{"id":"r2","text":"Carries water up"},{"id":"r3","text":"Make food"},{"id":"r1","text":"Take in water"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"ref":"q2","type":"multiple_choice","prompt":"Which part of a plant helps it make seeds?","hint":"It is often colourful.","explanation":"The flower helps the plant make seeds.","skill_tag":"plants.parts","options":[{"id":"a","text":"The root"},{"id":"b","text":"The stem"},{"id":"c","text":"The leaf"},{"id":"d","text":"The flower"}],"answer":["d"]},{"ref":"q3","type":"multi_select","prompt":"Which of these does a plant need to make food? Pick all that apply.","hint":"Think of the leaf picture.","explanation":"Plants make their own sugar using sunlight, water and carbon dioxide.","skill_tag":"photosynthesis.inputs","options":[{"id":"a","text":"Sugar"},{"id":"b","text":"Plastic"},{"id":"c","text":"Water"},{"id":"d","text":"Sunlight"}],"answer":["d","c"]},{"ref":"q4","type":"fill_blank","prompt":"Fill in the gaps about photosynthesis.","hint":"Plants clean the air for us.","explanation":"Plants take in carbon dioxide and give out oxygen.","skill_tag":"photosynthesis.outputs","points":2,"text":"Plants take in {b1} and give out {b2}.","blanks":[{"id":"b1","options":[{"id":"a","text":"oxygen"},{"id":"b","text":"sugar"},{"id":"c","text":"carbon dioxide"}]},{"id":"b2","options":[{"id":"a","text":"carbon dioxide"},{"id":"b","text":"pollen"},{"id":"c","text":"oxygen"}]}],"answer":{"b1":"c","b2":"c"}},{"ref":"q5","type":"hotspot","prompt":"Tap the part of the plant where food is made.","hint":"It catches the sunlight.","explanation":"Leaves make food.","skill_tag":"photosynthesis.where","scene":{"items":[{"id":"h1","emoji":"🍃","label":"leaf","x":25,"y":30,"size":3},{"id":"h2","emoji":"🌰","label":"seed","x":70,"y":30,"size":3},{"id":"h3","emoji":"🥕","label":"root","x":25,"y":75,"size":3},{"id":"h4","emoji":"🌸","label":"flower","x":75,"y":75,"size":3}],"show_labels":false},"answer":["h1"]},{"ref":"q6","type":"true_false","prompt":"A plant can make food without any sunlight.","hint":"Think about plants kept in a dark cupboard.","explanation":"Plants need sunlight to make food.","skill_tag":"photosynthesis.inputs","answer":[false]},{"ref":"q7","type":"slider","prompt":"A plant is kept in the sun and watered. After 6 days it has grown 3 cm each day. About how many cm tall is it?","hint":"Multiply the days by the growth.","explanation":"6 days of 3 cm is 6 x 3 = 18 cm.","skill_tag":"growth.measure","range":{"step":1,"min":0,"max":30,"unit":"cm"},"answer":{"value":18,"tolerance":1}},{"ref":"q8","type":"multiple_choice","prompt":"What is pollination?","hint":"A bee helps with it.","explanation":"Pollination is moving pollen from one flower to another.","skill_tag":"pollination.meaning","options":[{"id":"a","text":"Water going up the stem"},{"id":"b","text":"A leaf making sugar"},{"id":"c","text":"A seed starting to grow"},{"id":"d","text":"Moving pollen from flower to flower"}],"answer":["d"]},{"ref":"q9","type":"multiple_choice","prompt":"Why do bees visit flowers?","hint":"It is sweet.","explanation":"Bees collect nectar and carry pollen by accident.","skill_tag":"pollination.insects","options":[{"id":"a","text":"To dig soil"},{"id":"b","text":"To sleep"},{"id":"c","text":"To make shade"},{"id":"d","text":"For sweet nectar"}],"answer":["d"]},{"ref":"q10","type":"multi_select","prompt":"Which of these are ways a seed can travel? Pick all that apply.","hint":"Think of dandelions and coconuts.","explanation":"Seeds can be carried by wind, water or animals.","skill_tag":"seeds.dispersal","options":[{"id":"a","text":"Water"},{"id":"b","text":"Magnets"},{"id":"c","text":"Shadows"},{"id":"d","text":"Wind"}],"answer":["d","a"]},{"ref":"q11","type":"multiple_choice","prompt":"A coconut falls into the sea and floats to another beach. How was its seed spread?","hint":"It floated.","explanation":"Coconuts float, so water spreads the seeds.","skill_tag":"seeds.dispersal","options":[{"id":"a","text":"By wind"},{"id":"b","text":"By a magnet"},{"id":"c","text":"By a bee"},{"id":"d","text":"By water"}],"answer":["d"]},{"ref":"q12","type":"order","prompt":"Put the life cycle of a plant in order.","hint":"It starts with a seed.","explanation":"Seed, germination, adult plant, then new seeds.","skill_tag":"life_cycle.order","points":2,"items":[{"id":"i2","text":"Germination: root and shoot grow"},{"id":"i4","text":"Flowers make new seeds"},{"id":"i3","text":"An adult plant"},{"id":"i1","text":"A seed"}],"answer":["i1","i2","i3","i4"]},{"ref":"q13","type":"short_text","prompt":"What is the name for a seed starting to grow?","hint":"It starts with g.","explanation":"A seed starting to grow is germination.","skill_tag":"life_cycle.vocab","answer":{"accepted":["germination","germinate","germinating"]}},{"ref":"q14","type":"multiple_choice","prompt":"What does a seed need to germinate?","hint":"Think of planting in spring.","explanation":"Seeds need water and warmth to start growing.","skill_tag":"life_cycle.needs","options":[{"id":"a","text":"Only light"},{"id":"b","text":"Pollen"},{"id":"c","text":"A bee"},{"id":"d","text":"Water and warmth"}],"answer":["d"]},{"ref":"q15","type":"multiple_choice","prompt":"Which gas do people breathe in that plants give out?","hint":"Plants give us this gas.","explanation":"Plants give out oxygen, which we need to breathe.","skill_tag":"photosynthesis.outputs","options":[{"id":"a","text":"Steam"},{"id":"b","text":"Smoke"},{"id":"c","text":"Carbon dioxide"},{"id":"d","text":"Oxygen"}],"answer":["d"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'e18adba7-dfbb-5868-af14-96a689b39393', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 110, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
INSERT OR IGNORE INTO course_lessons (course_id, lesson_id, position, semester, week) VALUES ('90dc3e3c-b106-51e4-af87-bad3e017e698', 'e18adba7-dfbb-5868-af14-96a689b39393', 102, 1, 2);
