INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT '5ad77aef-bdb1-5296-a09b-9d354078dc30' || ':' || json_extract(e.value,'$.ref'), '5ad77aef-bdb1-5296-a09b-9d354078dc30', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) WHEN 'fill_blank' THEN json_object('text', json_extract(e.value,'$.text'), 'blanks', json_extract(e.value,'$.blanks')) WHEN 'hotspot' THEN json_object('scene', json_extract(e.value,'$.scene')) WHEN 'slider' THEN json_object('range', json_extract(e.value,'$.range')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = 'e18adba7-dfbb-5868-af14-96a689b39393';
